import {SOLO_NAMES,experience,equipmentClass} from './campaign-growth-data.mjs';
import {heroStats} from './campaign-profile.mjs';
import {SUMMON_RECTS,SUMMON_REGIONS,POOLS} from './summon-pools.mjs';
import {equippedArtifact,ARTIFACTS} from './campaign-artifacts.mjs';
import {artifactIconStyle} from './campaign-artifact-art.mjs';
import {archiveFrame,archiveStrip} from './archive-ui-art.mjs';

export function archivePortrait(hero){const r=SUMMON_RECTS[hero]||SUMMON_RECTS.fire,regions=SUMMON_REGIONS[hero]||SUMMON_REGIONS.fire,id='archive-silhouette-'+hero;return `<svg class="archive-hero-art" viewBox="${r.join(' ')}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${SOLO_NAMES[hero]}完整立绘"><defs><clipPath id="${id}" clipPathUnits="userSpaceOnUse">${regions.map(v=>`<rect x="${v[0]}" y="${v[1]}" width="${v[2]}" height="${v[3]}"/>`).join('')}</clipPath></defs><image href="assets/lobby/hero-splashes-v1.png" width="1536" height="1024" clip-path="url(#${id})"/></svg>`;}
export function renderArchiveCharacter(ui,p,w,h,token,sheet){
 const record=p.heroes[h],s=heroStats(p,h),xp=experience(record.exp),actor=w?.campaign?.team?.find(m=>m.hero===h)?.player||(w?.hero===h?w.player:null),hp=Math.ceil(actor?.hp??s.maxHp),mp=Math.floor(actor?.mp??s.maxMp),color=POOLS[h].color;
 const stats=[['攻击力',s.attack],['暴击率',(s.crit*100).toFixed(1)+'%'],['暴击伤害',Math.round(s.critDamage*100)+'%'],['攻击速度',s.attackSpeed.toFixed(2)+'×'],['吸血',(s.lifesteal*100).toFixed(1)+'%'],['生命回复',s.regen.toFixed(2)+' / 秒'],['法力回复',s.manaRegen.toFixed(2)+' / 秒'],['防御减伤',(s.armor*100).toFixed(1)+'%']];
 const targets=p.owned.filter(id=>id!==h),eligible=targets.filter(id=>experience(p.heroes[id].exp).level<5&&!p.heroes[id].receivedFrom),canTransfer=eligible.length>0&&!record.receivedFrom&&record.exp>0;
 const transferHelp='目标低于5级，每人只接收一次；传出者回到1级，装备和技能保留。接收的经验不可转传。';
 return `<div class="character-layout archive-layout" data-archive-hero="${h}" style="--hero-color:${color}">
 <section class="character-portrait archive-portrait">${archiveFrame('portrait')}<header class="character-level"><div class="archive-level-badge"><small>等级</small><b>Lv.${xp.level}</b></div><div class="archive-level-copy"><strong>${SOLO_NAMES[h]} · ${POOLS[h].title}</strong><small>${xp.xp} / ${xp.next} 经验</small><div class="archive-xp-track" role="progressbar" aria-label="角色经验" aria-valuenow="${xp.xp}" aria-valuemax="${xp.next}"><i style="width:${Math.min(100,xp.xp/xp.next*100)}%"></i>${archiveStrip('experience')}</div></div></header>
 <div class="archive-selector">${ui.selector(p,h).replace("查看英雄","切换角色")}</div><div class="archive-hero-stage">${archivePortrait(h)}</div><div class="archive-hero-actions"><div><button class="archive-primary" data-select-hero ${w?'disabled':''}>${archiveFrame('upgrade')}<span>${w?'关卡中':'设为出战英雄'}</span></button><button class="archive-summon" data-panel="summon">英雄召唤 ›</button></div></div></section>
 <section class="character-stats archive-stats"><section class="archive-attributes">${archiveFrame('attributes')}<h3>角色属性</h3><div class="archive-vitals">${[['生命',hp,s.maxHp,'health'],['法力',mp,s.maxMp,'mana']].map(([label,value,max,kind])=>`<div class="archive-vital ${kind}"><span>${label}</span><strong>${value} <small>/ ${max}</small></strong><i style="--fill:${Math.max(0,Math.min(100,value/max*100))}%"></i></div>`).join('')}</div><dl class="archive-attribute-list">${stats.map(([label,value])=>`<div class="attribute-cell"><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl></section>
 <div class="equipment-slots archive-equipment">${['weapon','armor','artifact'].map((slot,i)=>{const artifact=slot==='artifact'&&equippedArtifact(p),item=p.bag.find(v=>v.id===record.equipment[slot]);return `<div class="equipment-slot"><small>${['武器','盔甲','法器'][i]}</small>${artifact?`<button class="artifact-art equipment-artifact ${artifact}" style="${artifactIconStyle(artifact)}" data-panel="artifact" aria-label="查看${ARTIFACTS[artifact].name}"></button>`:item?token(item,{owner:h,hero:h,action:`data-gear-slot="${slot}"`}):`<button data-gear-slot="${slot}" aria-label="选择可装备${['武器','盔甲','法器'][i]}" class="empty-equipment" style="${sheet(i<2?i===0?'equipment':'armors':'ui',i<2?equipmentClass(h)==='melee'?0:6:3)}"></button>`}<span class="archive-slot-caption">${artifact?ARTIFACTS[artifact].name:item?'点击整备':'尚未装备'}</span></div>`;}).join('')}</div>
 <section class="power-transfer archive-transfer">${archiveFrame('transfer')}<div class="transfer-copy"><h4>传输功力 <span class="has-tip archive-help" tabindex="0" data-tip="${transferHelp}" aria-label="传输功力规则">?</span></h4><p>传出经验，承续新程</p></div><label class="transfer-target"><span class="sr-only">接收功力的英雄</span><select id="transfer-target" ${eligible.length?'':'disabled'}>${eligible.length?targets.map(id=>`<option value="${id}" ${eligible.includes(id)?'':'disabled'}>${SOLO_NAMES[id]} Lv.${experience(p.heroes[id].exp).level}${eligible.includes(id)?'':' · 不可接收'}</option>`).join(''):'<option value="">暂无可接收英雄</option>'}</select></label><button class="archive-primary" data-transfer ${!canTransfer||w?'disabled':''} title="${w?'请在关卡外传输功力':transferHelp}">${archiveFrame('upgrade')}<span>传输功力</span></button></section></section></div>`;
}
